import XCTest
@testable import OmniTAKMobile

// MARK: - XCTest stubs (require linked test target to execute)

final class TAKPacketCodecTests: XCTestCase {

    // MARK: - Unishox2 compress/decompress round-trip

    func testUnishox2CompressALPHA1() {
        let expected = Data(hexString: "804f1e3b4814ff")!
        let result = TAKPacketCodec.compress("ALPHA1")
        XCTAssertEqual(result, expected,
            "compress(ALPHA1) should produce 804f1e3b4814ff (golden vector)")
    }

    func testUnishox2CompressANDROID() {
        let expected = Data(hexString: "804e75babe80b4452091a55e69")!
        let result = TAKPacketCodec.compress("ANDROID-1234abcd")
        XCTAssertEqual(result, expected,
            "compress(ANDROID-1234abcd) should match golden vector")
    }

    func testUnishox2CompressMovingMessage() {
        let expected = Data(hexString: "879afabcf65148283d07ea0f5b9faa")!
        let result = TAKPacketCodec.compress("Moving to OBJ Bravo")
        XCTAssertEqual(result, expected,
            "compress(Moving to OBJ Bravo) golden vector")
    }

    func testUnishox2CompressEmpty() {
        let expected = Data(hexString: "97")!
        let result = TAKPacketCodec.compress("")
        XCTAssertEqual(result, expected, "compress(empty string) golden vector")
    }

    func testUnishox2CompressOverwatch() {
        let expected = Data(hexString: "857d3dfbcc73d8b45dbf")!
        let result = TAKPacketCodec.compress("Overwatch-7")
        XCTAssertEqual(result, expected, "compress(Overwatch-7) golden vector")
    }

    func testUnishox2CompressRTO() {
        let expected = Data(hexString: "86c20294f31de7824b571b7e07d8")!
        let result = TAKPacketCodec.compress("RTO actual, sitrep?")
        XCTAssertEqual(result, expected, "compress(RTO actual, sitrep?) golden vector")
    }

    func testUnishox2DecompressRoundTrip() {
        let texts = ["ALPHA1", "ANDROID-1234abcd", "Moving to OBJ Bravo",
                     "Overwatch-7", "RTO actual, sitrep?"]
        for text in texts {
            let compressed = TAKPacketCodec.compress(text)
            let decompressed = TAKPacketCodec.decompress(compressed)
            XCTAssertEqual(decompressed, text, "round-trip failed for: \(text)")
        }
    }

    // MARK: - PLI decode (golden wire vector)

    func testDecodePLIGoldenVector() {
        // PLI wire_hex from golden vectors — uncompressed, 57 bytes
        let wireHex = "121a0a06414c504841311210414e44524f49442d31323334616263641a040801100a220208552a110d3021601c15589a15b718382003288e02"
        guard let wireData = Data(hexString: wireHex) else {
            XCTFail("Failed to parse PLI wire hex"); return
        }

        guard let pkt = TAKPacketCodec.decode(wireData) else {
            XCTFail("TAKPacketCodec.decode returned nil for PLI golden vector"); return
        }

        XCTAssertFalse(pkt.isCompressed, "PLI golden vector should be is_compressed=false")
        XCTAssertEqual(pkt.callsign, "ALPHA1", "callsign should be ALPHA1")
        XCTAssertEqual(pkt.deviceCallsign, "ANDROID-1234abcd", "device_callsign mismatch")
        XCTAssertEqual(pkt.team, .cyan, "team should be Cyan (10)")
        XCTAssertEqual(pkt.role, .teamMember, "role should be TeamMember (1)")
        XCTAssertEqual(pkt.battery, 85, "battery should be 85")

        XCTAssertTrue(pkt.hasPLI, "should have PLI")
        XCTAssertEqual(pkt.latitudeI, 476062000, "latitude_i should be 476062000")
        XCTAssertEqual(pkt.longitudeI, -1223321000, "longitude_i should be -1223321000")
        XCTAssertEqual(pkt.altitude, 56, "altitude should be 56")
        XCTAssertEqual(pkt.speed, 3, "speed should be 3")
        XCTAssertEqual(pkt.course, 270, "course should be 270")

        // Convert to CoTEvent and verify lat/lon
        guard let event = TAKPacketCodec.toCoTEvent(pkt) else {
            XCTFail("toCoTEvent returned nil"); return
        }
        XCTAssertEqual(event.point.lat, 47.6062, accuracy: 1e-4, "lat should be ~47.6062")
        XCTAssertEqual(event.point.lon, -122.3321, accuracy: 1e-4, "lon should be ~-122.3321")
        XCTAssertEqual(event.detail.callsign, "ALPHA1")
        XCTAssertEqual(event.detail.team, "Cyan")
        XCTAssertEqual(event.type, "a-f-G-U-C")
    }

    // MARK: - GeoChat decode (golden wire vector, compressed)

    func testDecodeGeoChatGoldenVector() {
        let wireHex = "080112180a07804f1e3b4814ff120d804e75babe80b4452091a55e691a04080210052202084832210a0f879afabcf65148283d07ea0f5b9faa120e416c6c204368617420526f6f6d73"
        guard let wireData = Data(hexString: wireHex) else {
            XCTFail("Failed to parse GeoChat wire hex"); return
        }

        guard let pkt = TAKPacketCodec.decode(wireData) else {
            XCTFail("TAKPacketCodec.decode returned nil for GeoChat golden vector"); return
        }

        XCTAssertTrue(pkt.isCompressed, "GeoChat golden vector should be is_compressed=true")
        XCTAssertEqual(pkt.callsign, "ALPHA1", "callsign should decompress to ALPHA1")
        XCTAssertEqual(pkt.deviceCallsign, "ANDROID-1234abcd", "device_callsign should decompress")
        XCTAssertEqual(pkt.team, .red, "team should be Red (5)")
        XCTAssertEqual(pkt.role, .teamLead, "role should be TeamLead (2)")
        XCTAssertEqual(pkt.battery, 72, "battery should be 72")

        XCTAssertTrue(pkt.hasChat, "should have GeoChat")
        XCTAssertEqual(pkt.chatMessage, "Moving to OBJ Bravo")
        XCTAssertEqual(pkt.chatTo, "All Chat Rooms")

        guard let event = TAKPacketCodec.toCoTEvent(pkt) else {
            XCTFail("toCoTEvent returned nil for GeoChat"); return
        }
        XCTAssertEqual(event.type, "b-t-f")
        XCTAssertEqual(event.detail.remarks, "Moving to OBJ Bravo")
        XCTAssertEqual(event.detail.team, "Red")
    }

    // MARK: - Encode PLI and byte-match golden vector

    func testEncodePLIMatchesGoldenVector() {
        // Build CoTEvent matching the golden PLI fields exactly
        let event = CoTEvent(
            uid: "ANDROID-1234abcd",
            type: "a-f-G-U-C",
            time: Date(),
            point: CoTPoint(lat: 47.6062, lon: -122.3321, hae: 56.0, ce: 9999, le: 9999),
            detail: CoTDetail(
                callsign: "ALPHA1",
                team: "Cyan",
                teamRole: "TeamMember",
                speed: 3.0,
                course: 270.0,
                remarks: nil,
                battery: 85,
                device: nil,
                platform: nil
            )
        )

        guard let encoded = TAKPacketCodec.encode(event) else {
            XCTFail("TAKPacketCodec.encode returned nil"); return
        }

        let expectedHex = "121a0a06414c504841311210414e44524f49442d31323334616263641a040801100a220208552a110d3021601c15589a15b718382003288e02"
        let expected = Data(hexString: expectedHex)!

        XCTAssertEqual(encoded.hexString, expected.hexString,
            "Encoded PLI should byte-match the golden PLI wire_hex")
    }

    // MARK: - Format detection: Phase-1 TAKMessage payload still decodes via fallback

    func testPhase1TAKMessageFallback() {
        // A Phase-1 payload is a TAKMessage{CoTEvent} — field 2 is a LEN-delimited
        // CoTEvent submessage. TAKPacketCodec.decode should return nil for it,
        // and ATAKPluginParser.parseDetailed should fall back to parseTAKMessage.
        let phase1Event = CoTEvent(
            uid: "TEST-phase1-uid",
            type: "a-f-G-U-C",
            time: Date(timeIntervalSince1970: 1_714_000_000),
            point: CoTPoint(lat: 47.0, lon: -122.0, hae: 10, ce: 9999, le: 9999),
            detail: CoTDetail(callsign: "PHASE1-ALPHA", team: nil, teamRole: nil,
                              speed: nil, course: nil, remarks: nil, battery: nil,
                              device: nil, platform: nil)
        )

        let phase1Bytes = ATAKPluginSerializer.serialize(phase1Event)
        XCTAssertFalse(phase1Bytes.isEmpty)

        // TAKPacketCodec should NOT accept this (it's a TAKMessage, not TAKPacket)
        let takPacket = TAKPacketCodec.decode(phase1Bytes)
        // Note: may or may not be nil depending on accidental field overlap, but
        // must NOT decode as a valid PLI or chat
        if let pkt = takPacket {
            XCTAssertFalse(pkt.hasPLI && pkt.hasChat,
                "Phase-1 payload should not decode as both PLI and chat")
        }

        // ATAKPluginParser.parseDetailed should succeed via fallback
        guard let parsed = ATAKPluginParser.parseDetailed(phase1Bytes) else {
            XCTFail("Phase-1 payload should still parse via ATAKPluginParser fallback"); return
        }
        XCTAssertEqual(parsed.event.uid, "TEST-phase1-uid")
        XCTAssertEqual(parsed.event.type, "a-f-G-U-C")
        XCTAssertEqual(parsed.event.point.lat, 47.0, accuracy: 1e-6)
        XCTAssertEqual(parsed.event.point.lon, -122.0, accuracy: 1e-6)
    }
}

// MARK: - Data hex helpers (for test use only)

private extension Data {
    init?(hexString: String) {
        let hex = hexString.filter { $0.isHexDigit }
        guard hex.count % 2 == 0 else { return nil }
        var bytes: [UInt8] = []
        var idx = hex.startIndex
        while idx < hex.endIndex {
            let nextIdx = hex.index(idx, offsetBy: 2)
            guard let byte = UInt8(hex[idx..<nextIdx], radix: 16) else { return nil }
            bytes.append(byte)
            idx = nextIdx
        }
        self.init(bytes)
    }

    var hexString: String {
        map { String(format: "%02x", $0) }.joined()
    }
}


