    print("SKIP: unishox2-py3 not installed (pip3 install unishox2-py3)")
    sys.exit(0)

vectors = [
    ("ALPHA1",             "804f1e3b4814ff"),
    ("ANDROID-1234abcd",   "804e75babe80b4452091a55e69"),
    ("Moving to OBJ Bravo","879afabcf65148283d07ea0f5b9faa"),
