        print(f"    expected: {expected_hex}")
        all_ok = False
    # Round-trip check
    decompressed_bytes, n = unishox2.decompress(compressed, len(compressed))
    decompressed = decompressed_bytes.decode('utf-8', errors='replace')
    if decompressed != text:
        print(f"  FAIL: decompress round-trip for {repr(text)}: got {repr(decompressed)}")
        all_ok = False
