// Minimal standalone decoder (no OmniTAKMobile dependency)
private struct StandaloneDecoded {
    var isCompressed: Bool = false
    var callsign: String = ""
    var deviceCallsign: String = ""
    var team: UInt64 = 0
    var role: UInt64 = 0
    var battery: UInt32 = 0
    var latitudeI: Int32? = nil
    var longitudeI: Int32? = nil
    var altitude: Int32? = nil
    var speed: UInt32? = nil
    var course: UInt32? = nil
    var chatMessage: String? = nil
    var chatMessageRaw: [UInt8]? = nil
    var chatTo: String? = nil
    var chatToRaw: [UInt8]? = nil
    var hasChat: Bool { chatMessage != nil || chatMessageRaw != nil }
}

private func hexToData(_ hex: String) -> [UInt8] {
    var bytes: [UInt8] = []
    var idx = hex.startIndex
    while idx < hex.endIndex {
        let nextIdx = hex.index(idx, offsetBy: 2)
        if let byte = UInt8(hex[idx..<nextIdx], radix: 16) { bytes.append(byte) }
        idx = nextIdx
    }
    return bytes
}

private func readVarintStandalone(_ data: [UInt8], _ idx: inout Int) -> UInt64? {
    var result: UInt64 = 0; var shift: UInt64 = 0
    while idx < data.count {
        let byte = data[idx]; idx += 1
        result |= UInt64(byte & 0x7F) << shift
        if byte & 0x80 == 0 { return result }
        shift += 7
        if shift >= 64 { return nil }
    }
    return nil
}

private func readFixed32Standalone(_ data: [UInt8], _ idx: inout Int) -> UInt32? {
    guard idx + 4 <= data.count else { return nil }
    var v: UInt32 = 0
    for i in 0..<4 { v |= UInt32(data[idx+i]) << (8*i) }
    idx += 4; return v
}

private func readLDStandalone(_ data: [UInt8], _ idx: inout Int) -> [UInt8]? {
    guard let len = readVarintStandalone(data, &idx) else { return nil }
    let end = idx + Int(len)
    guard end <= data.count else { return nil }
    let slice = Array(data[idx..<end]); idx = end; return slice
}

private func skipStandalone(_ data: [UInt8], _ idx: inout Int, wire: UInt8) -> Bool {
    switch wire {
    case 0: return readVarintStandalone(data, &idx) != nil
    case 1: guard idx+8 <= data.count else { return false }; idx += 8; return true
    case 2:
        guard let len = readVarintStandalone(data, &idx) else { return false }
        let end = idx + Int(len); guard end <= data.count else { return false }; idx = end; return true
    case 5: guard idx+4 <= data.count else { return false }; idx += 4; return true
    default: return false
    }
}

/// Decode a TAKPacket without calling unishox2 (keeps chat.message as raw bytes).
private func decodeStandaloneRaw(_ data: [UInt8]) -> StandaloneDecoded? {
    var pkt = StandaloneDecoded(); var idx = 0
    while idx < data.count {
        guard let v = readVarintStandalone(data, &idx) else { break }
        let field = Int(v >> 3); let wire = UInt8(v & 0x07)
        switch (field, wire) {
        case (1, 0):
            guard let v2 = readVarintStandalone(data, &idx) else { return nil }
            pkt.isCompressed = v2 != 0
        case (2, 2): // contact
            guard let contactBytes = readLDStandalone(data, &idx) else { return nil }
            var ci = 0
            while ci < contactBytes.count {
                guard let cv = readVarintStandalone(contactBytes, &ci) else { break }
                let cf = Int(cv >> 3); let cw = UInt8(cv & 0x07)
                if cf == 1, cw == 2, let raw = readLDStandalone(contactBytes, &ci) {
                    pkt.callsign = String(bytes: raw, encoding: .utf8) ?? ""
                } else if cf == 2, cw == 2, let raw = readLDStandalone(contactBytes, &ci) {
                    pkt.deviceCallsign = String(bytes: raw, encoding: .utf8) ?? ""
                } else { _ = skipStandalone(contactBytes, &ci, wire: cw) }
            }
        case (3, 2): // group
            guard let groupBytes = readLDStandalone(data, &idx) else { return nil }
            var gi = 0
            while gi < groupBytes.count {
                guard let gv = readVarintStandalone(groupBytes, &gi) else { break }
                let gf = Int(gv >> 3); let gw = UInt8(gv & 0x07)
                if gf == 1, gw == 0, let rv = readVarintStandalone(groupBytes, &gi) { pkt.role = rv }
                else if gf == 2, gw == 0, let tv = readVarintStandalone(groupBytes, &gi) { pkt.team = tv }
                else { _ = skipStandalone(groupBytes, &gi, wire: gw) }
            }
        case (4, 2): // status
            guard let statusBytes = readLDStandalone(data, &idx) else { return nil }
            var si = 0
            while si < statusBytes.count {
                guard let sv = readVarintStandalone(statusBytes, &si) else { break }
                if Int(sv >> 3) == 1, UInt8(sv & 0x07) == 0,
                   let bv = readVarintStandalone(statusBytes, &si) { pkt.battery = UInt32(truncatingIfNeeded: bv) }
                else { _ = skipStandalone(statusBytes, &si, wire: UInt8(sv & 0x07)) }
            }
        case (5, 2): // pli
            guard let pliBytes = readLDStandalone(data, &idx) else { return nil }
            var pi = 0
            while pi < pliBytes.count {
                guard let pv = readVarintStandalone(pliBytes, &pi) else { break }
                let pf = Int(pv >> 3); let pw = UInt8(pv & 0x07)
                if pf == 1, pw == 5, let v32 = readFixed32Standalone(pliBytes, &pi) { pkt.latitudeI = Int32(bitPattern: v32) }
                else if pf == 2, pw == 5, let v32 = readFixed32Standalone(pliBytes, &pi) { pkt.longitudeI = Int32(bitPattern: v32) }
                else if pf == 3, pw == 0, let vv = readVarintStandalone(pliBytes, &pi) { pkt.altitude = Int32(bitPattern: UInt32(truncatingIfNeeded: vv)) }
                else if pf == 4, pw == 0, let vv = readVarintStandalone(pliBytes, &pi) { pkt.speed = UInt32(truncatingIfNeeded: vv) }
                else if pf == 5, pw == 0, let vv = readVarintStandalone(pliBytes, &pi) { pkt.course = UInt32(truncatingIfNeeded: vv) }
                else { _ = skipStandalone(pliBytes, &pi, wire: pw) }
            }
        case (6, 2): // chat
            guard let chatBytes = readLDStandalone(data, &idx) else { return nil }
            var chi = 0
            while chi < chatBytes.count {
                guard let chv = readVarintStandalone(chatBytes, &chi) else { break }
                let chf = Int(chv >> 3); let chw = UInt8(chv & 0x07)
                if chf == 1, chw == 2, let raw = readLDStandalone(chatBytes, &chi) {
                    pkt.chatMessageRaw = raw
                    pkt.chatMessage = String(bytes: raw, encoding: .utf8)
                } else if chf == 2, chw == 2, let raw = readLDStandalone(chatBytes, &chi) {
                    pkt.chatToRaw = raw
                    pkt.chatTo = String(bytes: raw, encoding: .utf8)
                } else { _ = skipStandalone(chatBytes, &chi, wire: chw) }
            }
        default: _ = skipStandalone(data, &idx, wire: wire)
        }
    }
    return pkt
}

/// Decode with decompression attempt (raw UTF-8 only — no unishox2 in standalone).
private func decodeStandalone(_ data: [UInt8]) -> StandaloneDecoded? {
    return decodeStandaloneRaw(data)
}

// Entry point when run standalone
runStandaloneReproducer()
